insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (11, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ゆうびんきょくで <u>切手</u>を かいます。', '["きって","ふうとう","はがき","きっぷ"]'::jsonb, 0, '切手 dibaca “きって” dan berarti perangko.', 'Bab 11–15 · Mondai 1 No.1', 'kanji:切手'),
  (11, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'としょかんに <u>留学生</u>が います。', '["りゅうがくせい","いしゃ","せんせい","がくせい"]'::jsonb, 0, '留学生 dibaca “りゅうがくせい” dan berarti pelajar asing.', 'Bab 11–15 · Mondai 1 No.2', 'kanji:留学生'),
  (11, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あきは <u>涼しい</u>です。', '["すずしい","あたたかい","さむい","あつい"]'::jsonb, 0, '涼しい dibaca “すずしい” dan berarti sejuk.', 'Bab 11–15 · Mondai 1 No.3', 'kanji:涼しい'),
  (11, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この カレーは とても <u>辛い</u>です。', '["からい","あまい","おもい","かるい"]'::jsonb, 0, '辛い dibaca “からい” dan berarti pedas.', 'Bab 11–15 · Mondai 1 No.4', 'kanji:辛い'),
  (11, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは <u>雨</u>です。', '["あめ","ゆき","くもり","てんき"]'::jsonb, 0, '雨 dibaca “あめ” dan berarti hujan.', 'Bab 11–15 · Mondai 1 No.5', 'kanji:雨'),
  (11, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもと こうえんで <u>遊びます</u>。', '["あそびます","つかれます","けっこんします","しょくじします"]'::jsonb, 0, '遊びます dibaca “あそびます” dan berarti bermain.', 'Bab 11–15 · Mondai 1 No.6', 'kanji:遊びます'),
  (11, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にちようびに ともだちと <u>泳ぎます</u>。', '["およぎます","あそびます","つかれます","けっこんします"]'::jsonb, 0, '泳ぎます dibaca “およぎます” dan berarti berenang.', 'Bab 11–15 · Mondai 1 No.7', 'kanji:泳ぎます'),
  (11, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんきを <u>消します</u>。', '["けします","つけます","あけます","しめます"]'::jsonb, 0, '消します dibaca “けします” dan berarti mematikan.', 'Bab 11–15 · Mondai 1 No.8', 'kanji:消します'),
  (11, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まどを <u>開けます</u>。', '["あけます","しめます","けします","つけます"]'::jsonb, 0, '開けます dibaca “あけます” dan berarti membuka.', 'Bab 11–15 · Mondai 1 No.9', 'kanji:開けます'),
  (11, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この まちに <u>住みます</u>。', '["すみます","つくります","うります","しります"]'::jsonb, 0, '住みます dibaca “すみます” dan berarti tinggal.', 'Bab 11–15 · Mondai 1 No.10', 'kanji:住みます'),
  (11, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きってを 2<u>まい</u> ください。', '["枚","台","回","人"]'::jsonb, 0, 'まい ditulis 枚, kata bantu bilangan untuk benda tipis seperti kertas.', 'Bab 11–15 · Mondai 2 No.11', 'kanji:枚'),
  (11, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'デパートで <u>ぎゅうどん</u>を たべます。', '["牛どん","天どん","焼肉","紅茶"]'::jsonb, 0, 'ぎゅうどん ditulis 牛どん, semangkuk nasi dengan daging sapi.', 'Bab 11–15 · Mondai 2 No.12', 'kanji:牛どん'),
  (11, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは <u>あめ</u>です。', '["雨","雪","曇り","天気"]'::jsonb, 0, 'あめ ditulis 雨, berarti hujan.', 'Bab 11–15 · Mondai 2 No.13', 'kanji:雨'),
  (11, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>せかい</u>には たくさん くにが あります。', '["世界","季節","名所","海"]'::jsonb, 0, 'せかい ditulis 世界, berarti dunia.', 'Bab 11–15 · Mondai 2 No.14', 'kanji:世界'),
  (11, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しゅうまつに <u>つり</u>を します。', '["釣り","散歩","買い物","食事"]'::jsonb, 0, 'つり ditulis 釣り, berarti memancing.', 'Bab 11–15 · Mondai 2 No.15', 'kanji:釣り'),
  (11, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃの <u>でぐち</u>は あちらです。', '["出口","入口","南口","北口"]'::jsonb, 0, 'でぐち ditulis 出口, berarti pintu keluar.', 'Bab 11–15 · Mondai 2 No.16', 'kanji:出口'),
  (11, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この <u>ちず</u>を みて ください。', '["地図","問題","答え","名前"]'::jsonb, 0, 'ちず ditulis 地図, berarti peta.', 'Bab 11–15 · Mondai 2 No.17', 'kanji:地図'),
  (11, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あには <u>けいさつかん</u>です。', '["警察官","外交官","政治家","運転手"]'::jsonb, 0, 'けいさつかん ditulis 警察官, berarti polisi.', 'Bab 11–15 · Mondai 2 No.18', 'kanji:警察官'),
  (11, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>いしゃ</u>は びょういんで はたらきます。', '["医者","看護師","教師","警察官"]'::jsonb, 0, 'いしゃ ditulis 医者, berarti dokter.', 'Bab 11–15 · Mondai 2 No.19', 'kanji:医者'),
  (11, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あには <u>かいしゃいん</u>です。', '["会社員","公務員","店員","運転手"]'::jsonb, 0, 'かいしゃいん ditulis 会社員, berarti pegawai perusahaan.', 'Bab 11–15 · Mondai 2 No.20', 'kanji:会社員'),
  (11, 'draft', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>やすみ</span><span class="arrange-chip"><b>③</b>だけ</span><span class="arrange-chip"><b>④</b>にちようび</span><span class="arrange-chip"><b>⑤</b>です。</span></div><small>Petunjuk arti: “Hari libur hanya hari Minggu saja.”</small>', '["②→①→④→③→⑤","①→②→④→③→⑤","②→④→①→③→⑤","②→①→③→④→⑤"]'::jsonb, 0, 'Urutan yang benar: ②やすみ→①は→④にちようび→③だけ→⑤です。 だけ berarti “hanya”, menunjukkan tidak ada yang lebih dari itu (Pel.11).', 'Bab 11–15 · Mondai 3 No.21', 'materi:book1:10:0'),
  (11, 'draft', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>30にん</span><span class="arrange-chip"><b>②</b>がっこう</span><span class="arrange-chip"><b>③</b>います。</span><span class="arrange-chip"><b>④</b>せんせい</span><span class="arrange-chip"><b>⑤</b>が</span><span class="arrange-chip"><b>⑥</b>ぐらい</span><span class="arrange-chip"><b>⑦</b>に</span></div><small>Petunjuk arti: “Di sekolah ada kira-kira 30 orang guru.”</small>', '["②→⑦→④→⑤→①→⑥→③","⑦→②→④→⑤→①→⑥→③","②→④→⑦→⑤→①→⑥→③","②→⑦→⑤→④→①→⑥→③"]'::jsonb, 0, 'Urutan yang benar: ②がっこう→⑦に→④せんせい→⑤が→①30にん→⑥ぐらい→③います。 ぐらい mengikuti Kata Keterangan Bilangan untuk menunjukkan perkiraan jumlah (Pel.11).', 'Bab 11–15 · Mondai 3 No.22', 'materi:book1:10:0'),
  (11, 'draft', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>より</span><span class="arrange-chip"><b>②</b>この</span><span class="arrange-chip"><b>③</b>おおきいです。</span><span class="arrange-chip"><b>④</b>くるま</span><span class="arrange-chip"><b>⑤</b>あの</span><span class="arrange-chip"><b>⑥</b>は</span><span class="arrange-chip"><b>⑦</b>くるま</span></div><small>Petunjuk arti: “Mobil ini lebih besar daripada mobil itu.”</small>', '["②→⑦→⑥→⑤→④→①→③","⑦→②→⑥→⑤→④→①→③","②→⑥→⑦→⑤→④→①→③","②→⑦→⑤→⑥→④→①→③"]'::jsonb, 0, 'Urutan yang benar: ②この→⑦くるま→⑥は→⑤あの→④くるま→①より→③おおきいです。 より menandai patokan pembanding: “Aより Bです” berarti B lebih ... daripada A (Pel.12).', 'Bab 11–15 · Mondai 3 No.23', 'materi:book1:11:0'),
  (11, 'draft', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>にほんりょうり</span><span class="arrange-chip"><b>②</b>てんぷら</span><span class="arrange-chip"><b>③</b>おいしいです。</span><span class="arrange-chip"><b>④</b>いちばん</span><span class="arrange-chip"><b>⑤</b>で</span><span class="arrange-chip"><b>⑥</b>が</span></div><small>Petunjuk arti: “Di antara masakan Jepang, tempura paling enak.”</small>', '["①→⑤→②→⑥→④→③","⑤→①→②→⑥→④→③","①→②→⑤→⑥→④→③","①→⑤→⑥→②→④→③"]'::jsonb, 0, 'Urutan yang benar: ①にほんりょうり→⑤で→②てんぷら→⑥が→④いちばん→③おいしいです。 で menunjukkan ruang lingkup untuk superlatif いちばん (Pel.12).', 'Bab 11–15 · Mondai 3 No.24', 'materi:book1:11:0'),
  (11, 'draft', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わたし</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>ほしいです。</span><span class="arrange-chip"><b>⑤</b>ともだち</span></div><small>Petunjuk arti: “Saya ingin punya teman.”</small>', '["①→②→⑤→③→④","②→①→⑤→③→④","①→⑤→②→③→④","①→②→③→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ①わたし→②は→⑤ともだち→③が→④ほしいです。 が menandai objek dari kata sifat 欲しい (Pel.13).', 'Bab 11–15 · Mondai 3 No.25', 'materi:book1:12:0'),
  (11, 'draft', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>たべたいです。</span><span class="arrange-chip"><b>③</b>わたし</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>てんぷら</span></div><small>Petunjuk arti: “Saya ingin makan tempura.”</small>', '["③→④→⑤→①→②","④→③→⑤→①→②","③→⑤→④→①→②","③→④→①→⑤→②"]'::jsonb, 0, 'Urutan yang benar: ③わたし→④は→⑤てんぷら→①を→②たべたいです。 を menandai objek dari Kata Kerja（bentuk ます）たいです (Pel.13).', 'Bab 11–15 · Mondai 3 No.26', 'materi:book1:12:0'),
  (11, 'draft', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>こうべ</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>へ</span><span class="arrange-chip"><b>④</b>かいもの</span><span class="arrange-chip"><b>⑤</b>いきます。</span></div><small>Petunjuk arti: “Pergi ke Kobe untuk belanja.”</small>', '["①→③→④→②→⑤","③→①→④→②→⑤","①→④→③→②→⑤","①→③→②→④→⑤"]'::jsonb, 0, 'Urutan yang benar: ①こうべ→③へ→④かいもの→②に→⑤いきます。 に menandai tujuan sebelum いきます／きます／かえります, dipakai untuk Kata Benda＋します (Pel.13).', 'Bab 11–15 · Mondai 3 No.27', 'materi:book1:12:0'),
  (11, 'draft', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>います。</span><span class="arrange-chip"><b>②</b>あめ</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>ふって</span><span class="arrange-chip"><b>⑤</b>で</span><span class="arrange-chip"><b>⑥</b>そと</span></div><small>Petunjuk arti: “Di luar sedang turun hujan.”</small>', '["⑥→⑤→②→③→④→①","⑤→⑥→②→③→④→①","⑥→②→⑤→③→④→①","⑥→⑤→③→②→④→①"]'::jsonb, 0, 'Urutan yang benar: ⑥そと→⑤で→②あめ→③が→④ふって→①います。 が menandai subjek dari kejadian alam yang dirasakan panca indera (Pel.14).', 'Bab 11–15 · Mondai 3 No.28', 'materi:book1:13:0'),
  (11, 'draft', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>から</span><span class="arrange-chip"><b>②</b>16ばん</span><span class="arrange-chip"><b>③</b>のって</span><span class="arrange-chip"><b>④</b>バス</span><span class="arrange-chip"><b>⑤</b>の</span><span class="arrange-chip"><b>⑥</b>きょうとえき</span><span class="arrange-chip"><b>⑦</b>ください。</span><span class="arrange-chip"><b>⑧</b>に</span></div><small>Petunjuk arti: “Silakan naik bus nomor 16 dari stasiun Kyoto.”</small>', '["⑥→①→②→⑤→④→⑧→③→⑦","①→⑥→②→⑤→④→⑧→③→⑦","⑥→②→①→⑤→④→⑧→③→⑦","⑥→①→⑤→②→④→⑧→③→⑦"]'::jsonb, 0, 'Urutan yang benar: ⑥きょうとえき→①から→②16ばん→⑤の→④バス→⑧に→③のって→⑦ください。 に menandai hasil dari Kata Kerja seperti のります (naik) (Pel.15).', 'Bab 11–15 · Mondai 3 No.29', 'materi:book1:14:0'),
  (11, 'draft', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>ください。</span><span class="arrange-chip"><b>③</b>じゅうしょ</span><span class="arrange-chip"><b>④</b>かいて</span><span class="arrange-chip"><b>⑤</b>ここ</span><span class="arrange-chip"><b>⑥</b>に</span></div><small>Petunjuk arti: “Tuliskan alamat di sini.”</small>', '["⑤→⑥→③→①→④→②","⑥→⑤→③→①→④→②","⑤→③→⑥→①→④→②","⑤→⑥→①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ⑤ここ→⑥に→③じゅうしょ→①を→④かいて→②ください。 に menandai tempat hasil dari Kata Kerja かきます, berbeda dari に yang menandai tujuan (Pel.15).', 'Bab 11–15 · Mondai 3 No.30', 'materi:book1:14:0'),
  (11, 'draft', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>やきゅう</span><span class="arrange-chip"><b>③</b>より</span><span class="arrange-chip"><b>④</b>おもしろいです。</span><span class="arrange-chip"><b>⑤</b>サッカー</span><span class="arrange-chip"><b>⑥</b>ほうが</span></div><small>Petunjuk arti: “Sepak bola lebih menarik daripada baseball.”</small>', '["⑤→①→⑥→②→③→④","①→⑤→⑥→②→③→④","⑤→⑥→①→②→③→④","⑤→①→②→⑥→③→④"]'::jsonb, 0, 'Urutan yang benar: ⑤サッカー→①の→⑥ほうが→②やきゅう→③より→④おもしろいです。 Pola AのほうがBよりKata Sifatです dipakai untuk membandingkan dua hal (Pel.12).', 'Bab 11–15 · Mondai 4 No.31', 'materi:book1:11:0'),
  (11, 'draft', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>くつ</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>で</span><span class="arrange-chip"><b>④</b>こうべ</span><span class="arrange-chip"><b>⑤</b>かいたいです。</span></div><small>Petunjuk arti: “Ingin membeli sepatu di Kobe.”</small>', '["④→③→①→②→⑤","③→④→①→②→⑤","④→①→③→②→⑤","④→③→②→①→⑤"]'::jsonb, 0, 'Urutan yang benar: ④こうべ→③で→①くつ→②を→⑤かいたいです。 Kata Kerja（bentuk ます）たいです menyatakan keinginan melakukan sesuatu (Pel.13).', 'Bab 11–15 · Mondai 4 No.32', 'materi:book1:12:0'),
  (11, 'draft', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>よみかた</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>おしえて</span><span class="arrange-chip"><b>④</b>ください。</span><span class="arrange-chip"><b>⑤</b>すみませんが</span><span class="arrange-chip"><b>⑥</b>この</span><span class="arrange-chip"><b>⑦</b>を</span><span class="arrange-chip"><b>⑧</b>かんじ</span></div><small>Petunjuk arti: “Maaf, tolong ajarkan cara membaca kanji ini.”</small>', '["⑤→⑥→⑧→②→①→⑦→③→④","⑥→⑤→⑧→②→①→⑦→③→④","⑤→⑧→⑥→②→①→⑦→③→④","⑤→⑥→②→⑧→①→⑦→③→④"]'::jsonb, 0, 'Urutan yang benar: ⑤すみませんが→⑥この→⑧かんじ→②の→①よみかた→⑦を→③おしえて→④ください。 Kata Kerja bentuk てください dipakai untuk meminta dengan sopan, biasanya didahului すみませんが (Pel.14).', 'Bab 11–15 · Mondai 4 No.33', 'materi:book1:13:0'),
  (11, 'draft', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>かけて</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>いま</span><span class="arrange-chip"><b>⑤</b>ミラーさん</span><span class="arrange-chip"><b>⑥</b>でんわ</span><span class="arrange-chip"><b>⑦</b>います。</span></div><small>Petunjuk arti: “Sdr. Miller sedang menelepon.”</small>', '["⑤→③→④→⑥→②→①→⑦","③→⑤→④→⑥→②→①→⑦","⑤→④→③→⑥→②→①→⑦","⑤→③→⑥→④→②→①→⑦"]'::jsonb, 0, 'Urutan yang benar: ⑤ミラーさん→③は→④いま→⑥でんわ→②を→①かけて→⑦います。 Kata Kerja bentuk ています menunjukkan aksi yang sedang berlangsung (Pel.14).', 'Bab 11–15 · Mondai 4 No.34', 'materi:book1:13:0'),
  (11, 'draft', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>しゃしん</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>いいですか。</span><span class="arrange-chip"><b>⑤</b>ここ</span><span class="arrange-chip"><b>⑥</b>とっても</span></div><small>Petunjuk arti: “Boleh mengambil foto di sini?”</small>', '["⑤→②→①→③→⑥→④","②→⑤→①→③→⑥→④","⑤→①→②→③→⑥→④","⑤→②→③→①→⑥→④"]'::jsonb, 0, 'Urutan yang benar: ⑤ここ→②で→①しゃしん→③を→⑥とっても→④いいですか。 Kata Kerja bentuk てもいいですか dipakai untuk meminta izin (Pel.15).', 'Bab 11–15 · Mondai 4 No.35', 'materi:book1:14:0'),
  (11, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　かいしゃに　がいこくじんの　しゃいんが　3にん　います。ミラーさんだけ　アメリカじんです。あとの　2にんは　ちゅうごくじんです。<br><small>アメリカじんは　なんにん　いますか。</small>', '["1にん","2にん","3にん","4にん"]'::jsonb, 0, 'だけ berarti “hanya”, jadi「ミラーさんだけアメリカじんです」berarti hanya Miller yang orang Amerika (1 orang), sedangkan 2 lainnya orang Tiongkok (Pel.11).', 'Bab 11–15 · Soal Cerita No.36', 'materi:book1:10:0'),
  (11, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　サッカーと　やきゅうと　どちらが　すきですか　と　きかれました。わたしは　サッカーの　ほうが　すきです。でも、３つの　スポーツの　中で　すいえいが　いちばん　すきです。<br><small>いちばん　すきな　スポーツは　なんですか。</small>', '["サッカー","やきゅう","すいえい","バスケット"]'::jsonb, 2, 'Meski「サッカーのほうがすき」(lebih suka sepak bola daripada baseball, perbandingan 2 hal dengan ほう), kalimat terakhir menegaskan「すいえいがいちばんすき」(renang yang PALING disuka dari 3 olahraga, superlatif dengan いちばん) — pola perbandingan 2 hal berbeda dari superlatif banyak hal (Pel.12).', 'Bab 11–15 · Soal Cerita No.37', 'materi:book1:11:0'),
  (11, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'らいしゅう、おきなわへ　いきたいです。おきなわで　なにを　しますか。……うみで　およぎたいです。それから、おいしい　りょうりも　たべたいです。<br><small>おきなわで　しない　ことは　なんですか。</small>', '["およぎます","りょうりを　たべます","かいものを　します","うみを　みます"]'::jsonb, 2, 'Cerita hanya menyebutkan dua keinginan:「およぎたいです」(ingin berenang) dan「りょうりをたべたいです」(ingin makan masakan) —「かいものをします」(berbelanja) tidak pernah disebutkan, jadi itu yang TIDAK dilakukan (Pel.13).', 'Bab 11–15 · Soal Cerita No.38', 'materi:book1:12:0'),
  (11, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ミラーさんは　いま　でんわを　かけて　います。ミラーさんは　IMCで　はたらいて　います。<br><small>「はたらいて　います」は　どんな　いみですか。</small>', '["いま　はたらいている　という　いみ","しごとが　IMCだ　という　いみ","でんわを　かけている　という　いみ","やすんでいる　という　いみ"]'::jsonb, 1, '「でんわをかけています」menunjukkan aksi yang SEDANG berlangsung, sedangkan「IMCではたらいています」menunjukkan STATUS pekerjaan (bekerja DI IMC), bukan sedang bekerja saat ini juga — dua fungsi berbeda dari ～ています (Pel.14/15).', 'Bab 11–15 · Soal Cerita No.39', 'materi:book1:13:0'),
  (11, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ここで　たばこを　すっても　いいですか。……すみません、ここは　きんえんですから、すっては　いけません。あそこの　へやなら、すっても　いいですよ。<br><small>どこで　たばこを　すっても　いいですか。</small>', '["ここ","きんえんのへや","あそこのへや","どこも　だめです"]'::jsonb, 2, 'Cerita menyatakan tempat ini きんえん (dilarang merokok) jadi「すってはいけません」(tidak boleh), TAPI「あそこのへやなら」(kalau di ruangan itu)「すってもいいです」(boleh) — pola てもいいです (izin) vs てはいけません (larangan) (Pel.15).', 'Bab 11–15 · Soal Cerita No.40', 'materi:book1:14:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (11, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ゆうびんきょくで <u>切手</u>を かいます。', '["きって","ふうとう","はがき","きっぷ"]'::jsonb, 0, '切手 dibaca “きって” dan berarti perangko.', 'Bab 11–15 · Mondai 1 No.1', 'kanji:切手'),
  (11, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'としょかんに <u>留学生</u>が います。', '["りゅうがくせい","いしゃ","せんせい","がくせい"]'::jsonb, 0, '留学生 dibaca “りゅうがくせい” dan berarti pelajar asing.', 'Bab 11–15 · Mondai 1 No.2', 'kanji:留学生'),
  (11, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あきは <u>涼しい</u>です。', '["すずしい","あたたかい","さむい","あつい"]'::jsonb, 0, '涼しい dibaca “すずしい” dan berarti sejuk.', 'Bab 11–15 · Mondai 1 No.3', 'kanji:涼しい'),
  (11, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この カレーは とても <u>辛い</u>です。', '["からい","あまい","おもい","かるい"]'::jsonb, 0, '辛い dibaca “からい” dan berarti pedas.', 'Bab 11–15 · Mondai 1 No.4', 'kanji:辛い'),
  (11, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは <u>雨</u>です。', '["あめ","ゆき","くもり","てんき"]'::jsonb, 0, '雨 dibaca “あめ” dan berarti hujan.', 'Bab 11–15 · Mondai 1 No.5', 'kanji:雨'),
  (11, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもと こうえんで <u>遊びます</u>。', '["あそびます","つかれます","けっこんします","しょくじします"]'::jsonb, 0, '遊びます dibaca “あそびます” dan berarti bermain.', 'Bab 11–15 · Mondai 1 No.6', 'kanji:遊びます'),
  (11, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にちようびに ともだちと <u>泳ぎます</u>。', '["およぎます","あそびます","つかれます","けっこんします"]'::jsonb, 0, '泳ぎます dibaca “およぎます” dan berarti berenang.', 'Bab 11–15 · Mondai 1 No.7', 'kanji:泳ぎます'),
  (11, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんきを <u>消します</u>。', '["けします","つけます","あけます","しめます"]'::jsonb, 0, '消します dibaca “けします” dan berarti mematikan.', 'Bab 11–15 · Mondai 1 No.8', 'kanji:消します'),
  (11, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まどを <u>開けます</u>。', '["あけます","しめます","けします","つけます"]'::jsonb, 0, '開けます dibaca “あけます” dan berarti membuka.', 'Bab 11–15 · Mondai 1 No.9', 'kanji:開けます'),
  (11, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この まちに <u>住みます</u>。', '["すみます","つくります","うります","しります"]'::jsonb, 0, '住みます dibaca “すみます” dan berarti tinggal.', 'Bab 11–15 · Mondai 1 No.10', 'kanji:住みます'),
  (11, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きってを 2<u>まい</u> ください。', '["枚","台","回","人"]'::jsonb, 0, 'まい ditulis 枚, kata bantu bilangan untuk benda tipis seperti kertas.', 'Bab 11–15 · Mondai 2 No.11', 'kanji:枚'),
  (11, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'デパートで <u>ぎゅうどん</u>を たべます。', '["牛どん","天どん","焼肉","紅茶"]'::jsonb, 0, 'ぎゅうどん ditulis 牛どん, semangkuk nasi dengan daging sapi.', 'Bab 11–15 · Mondai 2 No.12', 'kanji:牛どん'),
  (11, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'きょうは <u>あめ</u>です。', '["雨","雪","曇り","天気"]'::jsonb, 0, 'あめ ditulis 雨, berarti hujan.', 'Bab 11–15 · Mondai 2 No.13', 'kanji:雨'),
  (11, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>せかい</u>には たくさん くにが あります。', '["世界","季節","名所","海"]'::jsonb, 0, 'せかい ditulis 世界, berarti dunia.', 'Bab 11–15 · Mondai 2 No.14', 'kanji:世界'),
  (11, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しゅうまつに <u>つり</u>を します。', '["釣り","散歩","買い物","食事"]'::jsonb, 0, 'つり ditulis 釣り, berarti memancing.', 'Bab 11–15 · Mondai 2 No.15', 'kanji:釣り'),
  (11, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃの <u>でぐち</u>は あちらです。', '["出口","入口","南口","北口"]'::jsonb, 0, 'でぐち ditulis 出口, berarti pintu keluar.', 'Bab 11–15 · Mondai 2 No.16', 'kanji:出口'),
  (11, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この <u>ちず</u>を みて ください。', '["地図","問題","答え","名前"]'::jsonb, 0, 'ちず ditulis 地図, berarti peta.', 'Bab 11–15 · Mondai 2 No.17', 'kanji:地図'),
  (11, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あには <u>けいさつかん</u>です。', '["警察官","外交官","政治家","運転手"]'::jsonb, 0, 'けいさつかん ditulis 警察官, berarti polisi.', 'Bab 11–15 · Mondai 2 No.18', 'kanji:警察官'),
  (11, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>いしゃ</u>は びょういんで はたらきます。', '["医者","看護師","教師","警察官"]'::jsonb, 0, 'いしゃ ditulis 医者, berarti dokter.', 'Bab 11–15 · Mondai 2 No.19', 'kanji:医者'),
  (11, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あには <u>かいしゃいん</u>です。', '["会社員","公務員","店員","運転手"]'::jsonb, 0, 'かいしゃいん ditulis 会社員, berarti pegawai perusahaan.', 'Bab 11–15 · Mondai 2 No.20', 'kanji:会社員'),
  (11, 'published', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>やすみ</span><span class="arrange-chip"><b>③</b>だけ</span><span class="arrange-chip"><b>④</b>にちようび</span><span class="arrange-chip"><b>⑤</b>です。</span></div><small>Petunjuk arti: “Hari libur hanya hari Minggu saja.”</small>', '["②→①→④→③→⑤","①→②→④→③→⑤","②→④→①→③→⑤","②→①→③→④→⑤"]'::jsonb, 0, 'Urutan yang benar: ②やすみ→①は→④にちようび→③だけ→⑤です。 だけ berarti “hanya”, menunjukkan tidak ada yang lebih dari itu (Pel.11).', 'Bab 11–15 · Mondai 3 No.21', 'materi:book1:10:0'),
  (11, 'published', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>30にん</span><span class="arrange-chip"><b>②</b>がっこう</span><span class="arrange-chip"><b>③</b>います。</span><span class="arrange-chip"><b>④</b>せんせい</span><span class="arrange-chip"><b>⑤</b>が</span><span class="arrange-chip"><b>⑥</b>ぐらい</span><span class="arrange-chip"><b>⑦</b>に</span></div><small>Petunjuk arti: “Di sekolah ada kira-kira 30 orang guru.”</small>', '["②→⑦→④→⑤→①→⑥→③","⑦→②→④→⑤→①→⑥→③","②→④→⑦→⑤→①→⑥→③","②→⑦→⑤→④→①→⑥→③"]'::jsonb, 0, 'Urutan yang benar: ②がっこう→⑦に→④せんせい→⑤が→①30にん→⑥ぐらい→③います。 ぐらい mengikuti Kata Keterangan Bilangan untuk menunjukkan perkiraan jumlah (Pel.11).', 'Bab 11–15 · Mondai 3 No.22', 'materi:book1:10:0'),
  (11, 'published', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>より</span><span class="arrange-chip"><b>②</b>この</span><span class="arrange-chip"><b>③</b>おおきいです。</span><span class="arrange-chip"><b>④</b>くるま</span><span class="arrange-chip"><b>⑤</b>あの</span><span class="arrange-chip"><b>⑥</b>は</span><span class="arrange-chip"><b>⑦</b>くるま</span></div><small>Petunjuk arti: “Mobil ini lebih besar daripada mobil itu.”</small>', '["②→⑦→⑥→⑤→④→①→③","⑦→②→⑥→⑤→④→①→③","②→⑥→⑦→⑤→④→①→③","②→⑦→⑤→⑥→④→①→③"]'::jsonb, 0, 'Urutan yang benar: ②この→⑦くるま→⑥は→⑤あの→④くるま→①より→③おおきいです。 より menandai patokan pembanding: “Aより Bです” berarti B lebih ... daripada A (Pel.12).', 'Bab 11–15 · Mondai 3 No.23', 'materi:book1:11:0'),
  (11, 'published', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>にほんりょうり</span><span class="arrange-chip"><b>②</b>てんぷら</span><span class="arrange-chip"><b>③</b>おいしいです。</span><span class="arrange-chip"><b>④</b>いちばん</span><span class="arrange-chip"><b>⑤</b>で</span><span class="arrange-chip"><b>⑥</b>が</span></div><small>Petunjuk arti: “Di antara masakan Jepang, tempura paling enak.”</small>', '["①→⑤→②→⑥→④→③","⑤→①→②→⑥→④→③","①→②→⑤→⑥→④→③","①→⑤→⑥→②→④→③"]'::jsonb, 0, 'Urutan yang benar: ①にほんりょうり→⑤で→②てんぷら→⑥が→④いちばん→③おいしいです。 で menunjukkan ruang lingkup untuk superlatif いちばん (Pel.12).', 'Bab 11–15 · Mondai 3 No.24', 'materi:book1:11:0'),
  (11, 'published', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わたし</span><span class="arrange-chip"><b>②</b>は</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>ほしいです。</span><span class="arrange-chip"><b>⑤</b>ともだち</span></div><small>Petunjuk arti: “Saya ingin punya teman.”</small>', '["①→②→⑤→③→④","②→①→⑤→③→④","①→⑤→②→③→④","①→②→③→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ①わたし→②は→⑤ともだち→③が→④ほしいです。 が menandai objek dari kata sifat 欲しい (Pel.13).', 'Bab 11–15 · Mondai 3 No.25', 'materi:book1:12:0'),
  (11, 'published', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>たべたいです。</span><span class="arrange-chip"><b>③</b>わたし</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>てんぷら</span></div><small>Petunjuk arti: “Saya ingin makan tempura.”</small>', '["③→④→⑤→①→②","④→③→⑤→①→②","③→⑤→④→①→②","③→④→①→⑤→②"]'::jsonb, 0, 'Urutan yang benar: ③わたし→④は→⑤てんぷら→①を→②たべたいです。 を menandai objek dari Kata Kerja（bentuk ます）たいです (Pel.13).', 'Bab 11–15 · Mondai 3 No.26', 'materi:book1:12:0'),
  (11, 'published', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>こうべ</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>へ</span><span class="arrange-chip"><b>④</b>かいもの</span><span class="arrange-chip"><b>⑤</b>いきます。</span></div><small>Petunjuk arti: “Pergi ke Kobe untuk belanja.”</small>', '["①→③→④→②→⑤","③→①→④→②→⑤","①→④→③→②→⑤","①→③→②→④→⑤"]'::jsonb, 0, 'Urutan yang benar: ①こうべ→③へ→④かいもの→②に→⑤いきます。 に menandai tujuan sebelum いきます／きます／かえります, dipakai untuk Kata Benda＋します (Pel.13).', 'Bab 11–15 · Mondai 3 No.27', 'materi:book1:12:0'),
  (11, 'published', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>います。</span><span class="arrange-chip"><b>②</b>あめ</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>ふって</span><span class="arrange-chip"><b>⑤</b>で</span><span class="arrange-chip"><b>⑥</b>そと</span></div><small>Petunjuk arti: “Di luar sedang turun hujan.”</small>', '["⑥→⑤→②→③→④→①","⑤→⑥→②→③→④→①","⑥→②→⑤→③→④→①","⑥→⑤→③→②→④→①"]'::jsonb, 0, 'Urutan yang benar: ⑥そと→⑤で→②あめ→③が→④ふって→①います。 が menandai subjek dari kejadian alam yang dirasakan panca indera (Pel.14).', 'Bab 11–15 · Mondai 3 No.28', 'materi:book1:13:0'),
  (11, 'published', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>から</span><span class="arrange-chip"><b>②</b>16ばん</span><span class="arrange-chip"><b>③</b>のって</span><span class="arrange-chip"><b>④</b>バス</span><span class="arrange-chip"><b>⑤</b>の</span><span class="arrange-chip"><b>⑥</b>きょうとえき</span><span class="arrange-chip"><b>⑦</b>ください。</span><span class="arrange-chip"><b>⑧</b>に</span></div><small>Petunjuk arti: “Silakan naik bus nomor 16 dari stasiun Kyoto.”</small>', '["⑥→①→②→⑤→④→⑧→③→⑦","①→⑥→②→⑤→④→⑧→③→⑦","⑥→②→①→⑤→④→⑧→③→⑦","⑥→①→⑤→②→④→⑧→③→⑦"]'::jsonb, 0, 'Urutan yang benar: ⑥きょうとえき→①から→②16ばん→⑤の→④バス→⑧に→③のって→⑦ください。 に menandai hasil dari Kata Kerja seperti のります (naik) (Pel.15).', 'Bab 11–15 · Mondai 3 No.29', 'materi:book1:14:0'),
  (11, 'published', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>を</span><span class="arrange-chip"><b>②</b>ください。</span><span class="arrange-chip"><b>③</b>じゅうしょ</span><span class="arrange-chip"><b>④</b>かいて</span><span class="arrange-chip"><b>⑤</b>ここ</span><span class="arrange-chip"><b>⑥</b>に</span></div><small>Petunjuk arti: “Tuliskan alamat di sini.”</small>', '["⑤→⑥→③→①→④→②","⑥→⑤→③→①→④→②","⑤→③→⑥→①→④→②","⑤→⑥→①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ⑤ここ→⑥に→③じゅうしょ→①を→④かいて→②ください。 に menandai tempat hasil dari Kata Kerja かきます, berbeda dari に yang menandai tujuan (Pel.15).', 'Bab 11–15 · Mondai 3 No.30', 'materi:book1:14:0'),
  (11, 'published', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>やきゅう</span><span class="arrange-chip"><b>③</b>より</span><span class="arrange-chip"><b>④</b>おもしろいです。</span><span class="arrange-chip"><b>⑤</b>サッカー</span><span class="arrange-chip"><b>⑥</b>ほうが</span></div><small>Petunjuk arti: “Sepak bola lebih menarik daripada baseball.”</small>', '["⑤→①→⑥→②→③→④","①→⑤→⑥→②→③→④","⑤→⑥→①→②→③→④","⑤→①→②→⑥→③→④"]'::jsonb, 0, 'Urutan yang benar: ⑤サッカー→①の→⑥ほうが→②やきゅう→③より→④おもしろいです。 Pola AのほうがBよりKata Sifatです dipakai untuk membandingkan dua hal (Pel.12).', 'Bab 11–15 · Mondai 4 No.31', 'materi:book1:11:0'),
  (11, 'published', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>くつ</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>で</span><span class="arrange-chip"><b>④</b>こうべ</span><span class="arrange-chip"><b>⑤</b>かいたいです。</span></div><small>Petunjuk arti: “Ingin membeli sepatu di Kobe.”</small>', '["④→③→①→②→⑤","③→④→①→②→⑤","④→①→③→②→⑤","④→③→②→①→⑤"]'::jsonb, 0, 'Urutan yang benar: ④こうべ→③で→①くつ→②を→⑤かいたいです。 Kata Kerja（bentuk ます）たいです menyatakan keinginan melakukan sesuatu (Pel.13).', 'Bab 11–15 · Mondai 4 No.32', 'materi:book1:12:0'),
  (11, 'published', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>よみかた</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>おしえて</span><span class="arrange-chip"><b>④</b>ください。</span><span class="arrange-chip"><b>⑤</b>すみませんが</span><span class="arrange-chip"><b>⑥</b>この</span><span class="arrange-chip"><b>⑦</b>を</span><span class="arrange-chip"><b>⑧</b>かんじ</span></div><small>Petunjuk arti: “Maaf, tolong ajarkan cara membaca kanji ini.”</small>', '["⑤→⑥→⑧→②→①→⑦→③→④","⑥→⑤→⑧→②→①→⑦→③→④","⑤→⑧→⑥→②→①→⑦→③→④","⑤→⑥→②→⑧→①→⑦→③→④"]'::jsonb, 0, 'Urutan yang benar: ⑤すみませんが→⑥この→⑧かんじ→②の→①よみかた→⑦を→③おしえて→④ください。 Kata Kerja bentuk てください dipakai untuk meminta dengan sopan, biasanya didahului すみませんが (Pel.14).', 'Bab 11–15 · Mondai 4 No.33', 'materi:book1:13:0'),
  (11, 'published', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>かけて</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>いま</span><span class="arrange-chip"><b>⑤</b>ミラーさん</span><span class="arrange-chip"><b>⑥</b>でんわ</span><span class="arrange-chip"><b>⑦</b>います。</span></div><small>Petunjuk arti: “Sdr. Miller sedang menelepon.”</small>', '["⑤→③→④→⑥→②→①→⑦","③→⑤→④→⑥→②→①→⑦","⑤→④→③→⑥→②→①→⑦","⑤→③→⑥→④→②→①→⑦"]'::jsonb, 0, 'Urutan yang benar: ⑤ミラーさん→③は→④いま→⑥でんわ→②を→①かけて→⑦います。 Kata Kerja bentuk ています menunjukkan aksi yang sedang berlangsung (Pel.14).', 'Bab 11–15 · Mondai 4 No.34', 'materi:book1:13:0'),
  (11, 'published', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>しゃしん</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>いいですか。</span><span class="arrange-chip"><b>⑤</b>ここ</span><span class="arrange-chip"><b>⑥</b>とっても</span></div><small>Petunjuk arti: “Boleh mengambil foto di sini?”</small>', '["⑤→②→①→③→⑥→④","②→⑤→①→③→⑥→④","⑤→①→②→③→⑥→④","⑤→②→③→①→⑥→④"]'::jsonb, 0, 'Urutan yang benar: ⑤ここ→②で→①しゃしん→③を→⑥とっても→④いいですか。 Kata Kerja bentuk てもいいですか dipakai untuk meminta izin (Pel.15).', 'Bab 11–15 · Mondai 4 No.35', 'materi:book1:14:0'),
  (11, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　かいしゃに　がいこくじんの　しゃいんが　3にん　います。ミラーさんだけ　アメリカじんです。あとの　2にんは　ちゅうごくじんです。<br><small>アメリカじんは　なんにん　いますか。</small>', '["1にん","2にん","3にん","4にん"]'::jsonb, 0, 'だけ berarti “hanya”, jadi「ミラーさんだけアメリカじんです」berarti hanya Miller yang orang Amerika (1 orang), sedangkan 2 lainnya orang Tiongkok (Pel.11).', 'Bab 11–15 · Soal Cerita No.36', 'materi:book1:10:0'),
  (11, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　サッカーと　やきゅうと　どちらが　すきですか　と　きかれました。わたしは　サッカーの　ほうが　すきです。でも、３つの　スポーツの　中で　すいえいが　いちばん　すきです。<br><small>いちばん　すきな　スポーツは　なんですか。</small>', '["サッカー","やきゅう","すいえい","バスケット"]'::jsonb, 2, 'Meski「サッカーのほうがすき」(lebih suka sepak bola daripada baseball, perbandingan 2 hal dengan ほう), kalimat terakhir menegaskan「すいえいがいちばんすき」(renang yang PALING disuka dari 3 olahraga, superlatif dengan いちばん) — pola perbandingan 2 hal berbeda dari superlatif banyak hal (Pel.12).', 'Bab 11–15 · Soal Cerita No.37', 'materi:book1:11:0'),
  (11, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'らいしゅう、おきなわへ　いきたいです。おきなわで　なにを　しますか。……うみで　およぎたいです。それから、おいしい　りょうりも　たべたいです。<br><small>おきなわで　しない　ことは　なんですか。</small>', '["およぎます","りょうりを　たべます","かいものを　します","うみを　みます"]'::jsonb, 2, 'Cerita hanya menyebutkan dua keinginan:「およぎたいです」(ingin berenang) dan「りょうりをたべたいです」(ingin makan masakan) —「かいものをします」(berbelanja) tidak pernah disebutkan, jadi itu yang TIDAK dilakukan (Pel.13).', 'Bab 11–15 · Soal Cerita No.38', 'materi:book1:12:0'),
  (11, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ミラーさんは　いま　でんわを　かけて　います。ミラーさんは　IMCで　はたらいて　います。<br><small>「はたらいて　います」は　どんな　いみですか。</small>', '["いま　はたらいている　という　いみ","しごとが　IMCだ　という　いみ","でんわを　かけている　という　いみ","やすんでいる　という　いみ"]'::jsonb, 1, '「でんわをかけています」menunjukkan aksi yang SEDANG berlangsung, sedangkan「IMCではたらいています」menunjukkan STATUS pekerjaan (bekerja DI IMC), bukan sedang bekerja saat ini juga — dua fungsi berbeda dari ～ています (Pel.14/15).', 'Bab 11–15 · Soal Cerita No.39', 'materi:book1:13:0'),
  (11, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'ここで　たばこを　すっても　いいですか。……すみません、ここは　きんえんですから、すっては　いけません。あそこの　へやなら、すっても　いいですよ。<br><small>どこで　たばこを　すっても　いいですか。</small>', '["ここ","きんえんのへや","あそこのへや","どこも　だめです"]'::jsonb, 2, 'Cerita menyatakan tempat ini きんえん (dilarang merokok) jadi「すってはいけません」(tidak boleh), TAPI「あそこのへやなら」(kalau di ruangan itu)「すってもいいです」(boleh) — pola てもいいです (izin) vs てはいけません (larangan) (Pel.15).', 'Bab 11–15 · Soal Cerita No.40', 'materi:book1:14:0');
